from sys import stdin

def input():
	return stdin.readline().strip()

def read_int():
	return int(input())

def read_ints():
	return map(int, input().split())
t = read_int()
for case_num in range(t):
	(n, k) = read_ints()
	s = input()
	m = s.count('1')
	if m == 0:
		print(0)
	elif m == n:
		print(11 * (n - 1))
	else:
		ans = 11 * m
		l = s.find('1')
		r = s.rfind('1')
		lneed = l
		rneed = n - 1 - r
		if k >= lneed + rneed and m > 1:
			ans = 11 * (m - 1)
		elif k >= rneed:
			ans = 11 * m - 10
		elif k >= lneed:
			ans = 11 * m - 1
		print(ans)
